def forward(self, x):
    a = self.weave(x, selected=False)
    return self.bridge(a)

def weave(self, x, *, selected=False):
    a = x.sin()
    b = x.cos()
    c = x.tanh()
    y = a + b + c
    y = y.relu().sin().cos().tanh()
    if selected:
        return (y, a)
    return y

def weave(self, x, *, selected=False):
    a = x.sin()
    b = x.cos()
    c = x.tanh()
    y = a + b + c
    y = y.relu().sin().cos().tanh()
    if selected:
        return (y, a)
    return y

def bridge(self, x, *, option=None):
    a = x.sin()
    b = x.cos()
    c = x.tanh()
    return unfamiliar_bridge(a + b + c, option)
